"""Client that posts records to the ingestion API."""
import json
import urllib.error
import urllib.request

ENDPOINT = "https://ingest.internal.example.net/v2/records"


def load_records(path="records.json"):
    with open(path, "r", encoding="utf-8") as fh:
        return json.load(fh)


def post_record(endpoint, record):
    """POST one record. Return True if the API accepted it."""
    body = json.dumps(record).encode("utf-8")
    req = urllib.request.Request(
        endpoint, data=body, headers={"Content-Type": "application/json"}
    )
    try:
        with urllib.request.urlopen(req, timeout=10) as resp:
            return resp.status in (200, 201, 202)
    except urllib.error.HTTPError as err:
        print(f"record {record.get('id')!r} rejected (HTTP {err.code})")
    except urllib.error.URLError as err:
        print(f"record {record.get('id')!r} failed to send ({err.reason})")
    return False


def post_records(endpoint, records):
    accepted = 0
    for record in records:
        if post_record(endpoint, record):
            accepted += 1
    return accepted


def main():
    records = load_records()
    accepted = post_records(ENDPOINT, records)
    print(f"accepted {accepted}/{len(records)}")


if __name__ == "__main__":
    main()
